	private int getOperandSize(ISemanticRegion start) {
		int length = 0;
		ISemanticRegion currentNode = start;
		boolean end = false;
		while (!end) {
			length += currentNode.getText().length();
			currentNode = currentNode.getPreviousSemanticRegion();
			end = currentNode.getText().isBlank();
		}
		return length;
	}

